{
  "highlights": [
    {
      "start_time": 0,
      "end_time": 9000,
      "description": "蒙眼男子拄剑现身寿宴，当众宣告十年期限已到，向叶老头索要一半家产或偿命。"
    },
    {
      "start_time": 22000,
      "end_time": 26500,
      "description": "叶家小辈当众羞辱沈惊寒是瞎子，质疑他不配进入寿宴现场。"
    },
    {
      "start_time": 27000,
      "end_time": 37000,
      "description": "叶苍玄询问沈惊寒身份，沈惊寒提醒他可还记得沈玄一，叶苍玄面露疑惑。"
    },
    {
      "start_time": 39500,
      "end_time": 47000,
      "description": "沈惊寒自报是沈玄一的孙子，在场叶家小辈嘲讽他是来攀旧情的。"
    },
    {
      "start_time": 57000,
      "end_time": 65000,
      "description": "沈惊寒拒绝叶家赐座，拿出账本表明来意，称自己今日是来收账而非吃席。"
    },
    {
      "start_time": 67000,
      "end_time": 72500,
      "description": "叶少轩嚣张放话，让沈惊寒现在滚出寿宴还来得及。"
    },
    {
      "start_time": 73000,
      "end_time": 83000,
      "description": "叶苍玄摆出施舍姿态，称沈惊寒若缺钱可以赏他一笔，寿宴上不许胡闹。"
    },
    {
      "start_time": 83000,
      "end_time": 94000,
      "description": "沈惊寒当众反怼叶苍玄，直指叶家把欠债说成施舍、把赖账说成宽厚。"
    },
    {
      "start_time": 94000,
      "end_time": 99000,
      "description": "叶少轩拍桌大怒，骂沈惊寒是瞎子，竟敢在寿宴上撒野。"
    },
    {
      "start_time": 100000,
      "end_time": 112500,
      "description": "苏清颜认出沈惊寒是爷爷当年定下的娃娃亲对象，叶家小辈当众调侃此事。"
    },
    {
      "start_time": 126000,
      "end_time": 132000,
      "description": "苏宏远当众表态，苏家绝不会把女儿嫁给来历不明的瞎子。"
    },
    {
      "start_time": 133000,
      "end_time": 139000,
      "description": "苏母按住苏清颜，警告她不许乱说话，否则惹怒叶家她父亲不会饶她。"
    },
    {
      "start_time": 140000,
      "end_time": 147000,
      "description": "叶少轩走到沈惊寒身边嘲讽，称连苏家都不认他，还赖在这里做什么。"
    },
    {
      "start_time": 147000,
      "end_time": 159000,
      "description": "苏清颜担心沈惊寒想出声提醒，被父亲苏宏远强行拉走，勒令她不许多管闲事。"
    },
    {
      "start_time": 166000,
      "end_time": 175000,
      "description": "沈惊寒翻开天机账本，当众揭露叶苍玄当年借寿十年，今日正好到期。"
    },
    {
      "start_time": 200000,
      "end_time": 206000,
      "description": "叶苍玄被沈惊寒的借寿之说激怒，喝令手下将他轰出寿宴。"
    },
    {
      "start_time": 209000,
      "end_time": 216000,
      "description": "沈惊寒当众宣告清账规则，称叶家若不清账，借走的寿数将归还原主。"
    },
    {
      "start_time": 239000,
      "end_time": 246000,
      "description": "叶少轩走到沈惊寒面前当众辱骂，称他爷爷是乡野术士，敢在叶家装神弄鬼。"
    },
    {
      "start_time": 245000,
      "end_time": 255000,
      "description": "叶少轩嚣张威胁沈惊寒，要求他磕头赔罪并烧掉账本，否则就打断他的腿。"
    },
    {
      "start_time": 259000,
      "end_time": 272000,
      "description": "叶苍玄再次摆出施舍姿态，称沈惊寒想借旧情扬名是找错了地方。"
    },
    {
      "start_time": 273000,
      "end_time": 289000,
      "description": "叶苍玄拍桌而起，坚称叶家不欠沈惊寒任何东西，沈惊寒回怼欠不欠不是他说了算。"
    },
    {
      "start_time": 290000,
      "end_time": 299000,
      "description": "叶少轩将苏家牵扯进来，以沈惊寒与苏家的婚约为由，要求苏家给叶家一个说法。"
    },
    {
      "start_time": 324000,
      "end_time": 332000,
      "description": "苏宏远当众拿出婚书，宣布苏家与沈惊寒的婚约就此作废。"
    },
    {
      "start_time": 333000,
      "end_time": 347500,
      "description": "沈惊寒接过婚书，表示婚约可以退，但这是爷爷亲笔所写，不许苏家扔掉。"
    },
    {
      "start_time": 356000,
      "end_time": 364000,
      "description": "沈惊寒拿出涛契笔，最后质问叶苍玄，是交一半家产清账还是还寿。"
    },
    {
      "start_time": 378000,
      "end_time": 390000,
      "description": "沈惊寒落笔催债，叶苍玄佛珠散落、瞬间衰老，当场认出沈玄一的名号。"
    },
    {
      "start_time": 414000,
      "end_time": 427000,
      "description": "沈惊寒临走前放话，限叶家三天内交一半家产到天机当铺，否则下次收的将不是寿数。"
    },
    {
      "start_time": 428000,
      "end_time": 445000,
      "description": "叶家手下群攻沈惊寒，被他仅凭一根拐杖尽数击倒，叶少轩当众怒骂手下废物。"
    },
    {
      "start_time": 460000,
      "end_time": 470000,
      "description": "叶少轩气急败坏，下令去请白老并通知萧擎天出面对付沈惊寒。"
    },
    {
      "start_time": 503000,
      "end_time": 506500,
      "description": "苏清颜追问沈惊寒接下来的去向，沈惊寒称自己会等“他们”来找。"
    },
    {
      "start_time": 530000,
      "end_time": 536000,
      "description": "沈惊寒回到天机当铺旧址翻查账本，发现下一笔债的债户是萧擎天，借了三成武骨未清。"
    },
    {
      "start_time": 544000,
      "end_time": 553000,
      "description": "萧擎天带人闯入天机当铺旧址，见地方破旧，出言嘲讽沈惊寒寒酸。"
    },
    {
      "start_time": 578000,
      "end_time": 582000,
      "description": "萧擎天提及叶老太爷被气病一事，沈惊寒冷淡回应自己只收账不治病。"
    },
    {
      "start_time": 598000,
      "end_time": 610000,
      "description": "萧擎天向沈惊寒提出三个苛刻条件，要求他下跪道歉、烧掉账本并永远滚出江南。"
    },
    {
      "start_time": 642000,
      "end_time": 657500,
      "description": "沈惊寒当众点破萧擎天十年前跪求借三成武骨的往事，称若拒不还债将修为尽失当场暴毙。"
    },
    {
      "start_time": 676000,
      "end_time": 684000,
      "description": "萧擎天被彻底震惊，追问沈惊寒到底是谁，沈惊寒坦言自己是沈玄一的孙子。"
    },
    {
      "start_time": 748000,
      "end_time": 755000,
      "description": "萧擎天得知沈惊寒身份后，当场单膝下跪行礼，口称沈少。"
    },
    {
      "start_time": 775000,
      "end_time": 795000,
      "description": "萧擎天当场宣布与叶家断绝供奉关系，称叶家欠沈少的债就是欠他老板的，不再接叶家的活。"
    }
  ],
